<script>
// ---- TICKER DUPLICATION ----
function duplicateTicker(tickerEl) {
  const children = Array.from(tickerEl.children);
  children.forEach(child => {
    tickerEl.appendChild(child.cloneNode(true));
  });
}

// ---- HEALTH TOPICS CAROUSEL ----
function scrollCarousel(direction) {
  const container = document.getElementById('topics-carousel');
  const scrollAmount = 320;
  container.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
}

// ---- RECOMMENDED READS TABS ----
function switchTab(category, btn) {
  // Update active button
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');

  // Show/hide articles
  document.querySelectorAll('#articles-grid .article-card').forEach(card => {
    if (card.dataset.category === category) {
      card.classList.remove('hidden');
    } else {
      card.classList.add('hidden');
    }
  });
}

// ---- NEWSLETTER SIGNUP ----
function handleNewsletterSubmit(e) {
  e.preventDefault();
  const email = document.getElementById('newsletter-email').value;
  if (email) {
    document.getElementById('newsletter-form').style.display = 'none';
    document.querySelector('.newsletter-cta .privacy-note').style.display = 'none';
    document.getElementById('newsletter-success').style.display = 'block';
  }
  return false;
}

// ---- FOOTER SIGNUP ----
function handleFooterSubmit(e) {
  e.preventDefault();
  const email = document.getElementById('footer-email').value;
  if (email) {
    document.getElementById('footer-email').value = '';
    document.getElementById('footer-success').style.display = 'block';
    setTimeout(() => {
      document.getElementById('footer-success').style.display = 'none';
    }, 3000);
  }
  return false;
}

// ---- MOBILE NAV DROPDOWNS ----
document.querySelectorAll('.nav-item').forEach(item => {
  item.addEventListener('click', function(e) {
    if (window.innerWidth <= 768) {
      const menu = this.querySelector('.mega-menu');
      if (menu) {
        const isVisible = menu.style.display === 'block';
        menu.style.display = isVisible ? 'none' : 'block';
        e.preventDefault();
      }
    }
  });
});
</script>

